class Solution:
    def summaryRanges(self, nums: List[int]) -> List[str]:
        if not nums:
            return []
        def fmt(s, e):
            return str(s) if s == e else f"{s}->{e}"
        result = []
        start = nums[0]
        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1] + 1:
                continue
            result.append(fmt(start, nums[i - 1]))
            start = nums[i]
        result.append(fmt(start, nums[-1]))
        return result
```

